class Particle:
    # duty: Particle.__init__
    def __init__(self, x0):
        self.position_i = list(x0)
        self.velocity_i = [random.uniform(-1, 1) for _ in self.position_i]
        self.pos_best_i = list(x0)
        self.err_best_i = float("inf")
