        prev_close = df["close"].iloc[0]
        prev_brick = int(np.floor(prev_close / brick)) * brick
        uptrend = True
        for close in df["close"].iloc[1:]:
            diff = close - prev_brick
            n = int(abs(diff) // brick)
            if n == 0:
                continue
            direction = 1 if diff > 0 else -1
            for _ in range(n):
                open_ = prev_brick
                close_ = prev_brick + direction * brick
