                    low = close_
                bricks.append(
                    {
                        "open": open_,
                        "high": high,
                        "low": low,
                        "close": close_,
                        "uptrend": direction > 0,
                    }
                )
                prev_brick = close_
        self._bricks = pd.DataFrame(
            bricks, columns=["open", "high", "low", "close", "uptrend"]
        )
        return self._bricks

