import numpy as np
import pandas as pd


class Instrument:
    # duty: Instrument.__init__
    def __init__(self, df):
        self.odf = df
        self.df = df.copy()
        self._validate_df()

    # duty: Instrument._validate_df
    def _validate_df(self):
        if not isinstance(self.df, pd.DataFrame):
            raise ValueError("Input must be a pandas DataFrame.")
        if self.df.empty:
            raise ValueError("Input DataFrame must not be empty.")
        # Normalize column names to lowercase for consistency.
        self.df.columns = [str(c).strip().lower() for c in self.df.columns]
        required = ['open', 'high', 'low', 'close']
        missing = [c for c in required if c not in self.df.columns]
        if missing:
            raise ValueError(
                "DataFrame is missing required OHLC columns: {}".format(missing)
            )
        for c in required:
            self.df[c] = pd.to_numeric(self.df[c], errors='coerce')
        if self.df[required].isnull().any().any():
            raise ValueError("OHLC columns contain non-numeric or null values.")


class Renko(Instrument):
    PERIOD_CLOSE = 1
    PRICE_MOVEMENT = 2
    TREND_CHANGE_DIFF = 1

    def __init__(self, df, brick_size=10.0, chart_type=PERIOD_CLOSE):
        super().__init__(df)
        self.brick_size = brick_size
        self.chart_type = chart_type
        self._bricks = []

    def get_ohlc_data(self):
        if self.chart_type == self.PERIOD_CLOSE:
            return self.period_close_bricks()
        return self.price_movement_bricks()

    def price_movement_bricks(self):
        pass

    # duty: Renko.period_close_bricks
    def period_close_bricks(self):
        closes = self.df['close'].values
        n = len(closes)
        if n == 0:
            return pd.DataFrame(
                columns=['date', 'open', 'high', 'low', 'close', 'uptrend']
            )

        brick = self.brick_size
        rows = []

        # Seed the first brick from the first close price.
        first_close = closes[0]
        rows.append({
            'date': self.df.index[0],
            'open': first_close,
            'high': first_close,
            'low': first_close,
            'close': first_close,
            'uptrend': True,
        })

        last_close = first_close
        uptrend = True

        for i in range(1, n):
            close = closes[i]
            diff = close - last_close

            if uptrend:
                if diff >= brick:
                    # Extend uptrend by one or more bricks.
                    num = int(diff // brick)
                    for _ in range(num):
                        new_close = last_close + brick
                        rows.append({
                            'date': self.df.index[i],
                            'open': last_close,
                            'high': new_close,
                            'low': last_close,
                            'close': new_close,
                            'uptrend': True,
                        })
                        last_close = new_close
                elif diff <= -2 * brick:
                    # Reversal to downtrend requires two bricks of movement.
                    num = int(abs(diff) // brick)
                    for _ in range(num):
                        new_close = last_close - brick
                        rows.append({
                            'date': self.df.index[i],
                            'open': last_close,
                            'high': last_close,
                            'low': new_close,
                            'close': new_close,
                            'uptrend': False,
                        })
                        last_close = new_close
                    uptrend = False
            else:
