        self.df = df
        self.line_number = line_number
        self._validate_df()

    def _validate_df(self):
        required = {"date", "open", "high", "low", "close"}
        cols = {c.lower() for c in self.df.columns}
        if not required.issubset(cols):
            raise ValueError(
                "DataFrame must contain date, open, high, low and close columns"
            )
        self.df = self.df.rename(columns={c: c.lower() for c in self.df.columns})
        self.df = self.df.reset_index(drop=True)

    # duty: LineBreak.uptrend_reversal
    def uptrend_reversal(self, close: float) -> bool:
        """Return True if ``close`` breaks below the low of the last
        ``line_number`` lines while the chart is currently in an uptrend."""
        if len(self.df) < self.line_number:
            return False
        lows = self.df["low"].iloc[-self.line_number:]
        return close < lows.min()

    # duty: LineBreak.downtrend_reversal
    def downtrend_reversal(self, close: float) -> bool:
        """Return True if ``close`` breaks above the high of the last
        ``line_number`` lines while the chart is currently in a downtrend."""
        if len(self.df) < self.line_number:
            return False
        highs = self.df["high"].iloc[-self.line_number:]
        return close > highs.max()

